function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
;


dx(1)=((0.11*x(3)/ (0.006*x(1)+x(3)))*x(1)-( u(1)*x(1)/(500*x(4)))                                                                                                        )*tal;
dx(2)=((0.0055*x(3)/(0.0001 + x(3)*(1 + 10*x(3))))*x(1)-0.01*x(2) - u(1)*x(2)/(500*x(4))                                                                                  )*tal;
dx(3)=(-((0.11*x(3)/ (0.006*x(1)+x(3)))*x(1)/0.47) - ((0.0055*x(3)/(0.0001 + x(3)*(1 + 10*x(3))))*x(1)/1.2) - (x(1)*0.029*x(3)/(0.0001+x(3))) + (u(1)*((1-x(3)/500)/x(4))))*tal;
dx(4)=(u(1)/500                                                                                                                                                           )*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
